import React, { useEffect } from 'react';
import Hero from './Hero';
import IndustrySection from './IndustrySection';
import AcademicsSection from './AcademicsSection';
import ProjectsSection from './ProjectsSection';
import './MinimalPortfolio.css';

const MinimalPortfolio = ({ launch3D }) => {
  // Ensure scrolling is enabled for 2D experience
  useEffect(() => {
    document.body.style.overflow = '';
    document.body.style.position = '';
    document.body.style.height = '';
    
    // Cleanup function - don't interfere when component unmounts
    return () => {
      // Don't reset styles when switching to 3D
    };
  }, []);
  return (
    <div className="minimal-portfolio">
      <div className="banner-3d" onClick={launch3D}>
        <button className="launch-3d-btn">
          Launch 3D Experience
        </button>
      </div>
      
      <div className="portfolio-content">
        <Hero />
        <div className="sections-container">
          <div className="experience-sections">
            <IndustrySection />
            <AcademicsSection />
          </div>
          <ProjectsSection />
        </div>
      </div>
    </div>
  );
};

export default MinimalPortfolio;