import React from 'react';

const Hero = () => {
  return (
    <div className="hero">
      <div className="hero-content">
        <img 
          src="images/pfp-face.jpg" 
          alt="Subhash Prasad" 
          className="profile-photo"
        />
        <div className="hero-text">
          <h1 className="name">Subhash Prasad</h1>
          <p className="subtitle">EECS @ UC Berkeley</p>

          <div className="social-links">
            <a 
              href="https://linkedin.com/in/subhash-prasad" 
              target="_blank" 
              rel="noopener noreferrer"
              className="social-link"
            >
              <img 
                src="images/linkedin.png" 
                alt="LinkedIn" 
                className="social-icon"
              />
            </a>
            <a 
              href="https://github.com/subhashjprasad" 
              target="_blank" 
              rel="noopener noreferrer"
              className="social-link"
            >
              <img 
                src="images/github.png" 
                alt="GitHub" 
                className="social-icon"
              />
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Hero;