import { Physics } from '@react-three/rapier'
import Lights from './Lights.jsx'
import { Level } from './Level.jsx'
import Player from './Player.jsx'
import { Text3D } from '@react-three/drei'
import { Perf } from 'r3f-perf'

export default function Experience()
{
    return <>

        <color args={ [ '#C5F3FC' ] } attach="background" />

        <Perf position="top-left" />
        
        <Physics 
            debug={false}
            timeStep={1/60}
            paused={false}
            interpolate={true}
            updatePriority={-50}
        >
            <Lights />
            <Level />
            <Player />
        </Physics>

        <Text3D 
            font="./fonts/helvetiker_regular.typeface.json" 
            position = {[-3, 2, 0]}
            size={ 0.5 }
            height={ 0.1 }
            curveSegments={ 8 }
            bevelEnabled={ true }
            bevelSize={ 0.01 }
            bevelThickness={ 0.01 }
            bevelSegments={ 3 }
        >
            WASD + Spacebar
            <meshStandardMaterial color="#333" />
        </Text3D>
        <Text3D 
            font="./fonts/helvetiker_regular.typeface.json" 
            position = {[-2.2, 3, 0]}
            size={ 0.2 }
            height={ 0.06 }
            curveSegments={ 6 }
            bevelEnabled={ true }
            bevelSize={ 0.005 }
            bevelThickness={ 0.005 }
            bevelSegments={ 2 }
        >
            (still very much a work in progress)
            <meshStandardMaterial color="#666" />
        </Text3D>
        <Text3D 
            font="./fonts/helvetiker_regular.typeface.json" 
            position = {[-1.5, -2, 0]}
            size={ 0.15 }
            height={ 0.04 }
            curveSegments={ 5 }
            bevelEnabled={ true }
            bevelSize={ 0.003 }
            bevelThickness={ 0.003 }
            bevelSegments={ 2 }
        >
            Press F5 to return to portfolio
            <meshStandardMaterial color="#888" />
        </Text3D>

    </>
}