import React from 'react';

const academicExperiences = [
  {
    organization: "Berkeley Speech Group (BAIR)",
    logo: "images/bsg.png",
    title: "Student Researcher",
    duration: "Sep 2025 - Present",
    type: "Research",
    description: "• Implementing <span class='highlight-word'>MLP</span>, <span class='highlight-word'>LSTM</span>, and <span class='highlight-word'>transformer</span> architectures to produce detailed <span class='highlight-word'>guitar tablature</span> with expressive labels directly from audio<br>• Researching intelligent <span class='highlight-word'>generative</span> methods to create <span class='highlight-word'>original musical content</span> and backing tracks based on <span class='highlight-word'>user input/style preferences</span>",
    technologies: ["Machine Learning", "Transformers", "Generative AI", "Audio Signal Processing", "Python"]
  },
  {
    organization: "Redwood Center for Theoretical Neuroscience (BAIR)",
    logo: "images/redwood.jpg",
    title: "Student Researcher",
    duration: "Oct 2024 - Feb 2025",
    type: "Research",
    description: "• Optimized process of solving hard combinatorial problems such as <span class='highlight-word'>boolean satisfiability</span> (k-SAT) with postdoctoral fellow Connor Bybee<br>• Researched <span class='highlight-word'>coupled-oscillator</span> implementation of <span class='highlight-word'>Ising machines</span> along with techniques like chaos integration to escape local minima<br>• Benchmarked performance of varying <span class='highlight-word'>higher-order Ising models</span> with <span class='highlight-word'>sub-harmonic injection locking</span> (SHIL) using <span class='highlight-word'>Google JAX</span> + <span class='highlight-word'>Diffrax</span>",
    technologies: ["Google JAX", "Machine Learning", "Optimization", "Python"]
  },
  {
    organization: "COMPSCI 170 - Algorithms",
    logo: "images/berkeley.jpg",
    title: "Course Staff",
    duration: "Aug 2025 - Present",
    type: "Course Staff / Development",
    description: "• Performing administrative & pedagogical duties for <span class='highlight-word'>CS 170 - Efficient Algorithms & Intractable Problems</span><br>• Grading homework & tests; monitoring & answering <span class='highlight-word'>student questions</span> on classwide Ed discussion forum<br>• Hosting drop-in <span class='highlight-word'>office hours</span> for students; assisting students during weekly <span class='highlight-word'>discussion</span> sections",
    technologies: ["Algorithms", "Programming", "Mathematics", "Teaching"]
  },
  {
    organization: "COMPSCI 198 - Esolangs",
    logo: "images/berkeley.jpg",
    title: "Instructor",
    duration: "Jan 2025 - May 2025",
    type: "Course Staff / Development",
    description: "• <span class='highlight-word'>Teaching</span> 2-unit DeCal (student-run class) <span class='highlight-word'>COMPSCI 198 - Esoteric Programming Languages</span><br>• Course covers various esolangs and their corresponding <span class='highlight-word'>history, syntax, usage, pitfalls,</span> and <span class='highlight-word'>purpose</span><br>• Making weekly assignments that test students' <span class='highlight-word'>problem solving</span> skills when <span class='highlight-word'>constrained</span> by an esolang<br>• Curating course content; presenting weekly <span class='highlight-word'>lectures</span>; handling administrative duties like grading",
    technologies: ["Programming Language Design", "Algorithms", "Teaching"]
  },
  {
    organization: "COMPSCI 70 - Discrete Math & Probability",
    logo: "images/berkeley.jpg",
    title: "Course Staff",
    duration: "Aug 2024 - May 2025",
    type: "Course Staff / Development",
    description: "• Performing administrative & pedagogical duties for <span class='highlight-word'>CS 70 - Discrete Mathematics & Probability Theory</span><br>• Grading homework & tests; monitoring & answering <span class='highlight-word'>student questions</span> on classwide Ed discussion forum<br>• Hosting drop-in <span class='highlight-word'>office hours</span> for students; assisting students during weekly <span class='highlight-word'>discussion</span> sections",
    technologies: ["Mathematics", "Algorithms", "Teaching"]
  },
];

const AcademicsSection = () => {
  const getOrganizationClass = (organization) => {
    const organizationMap = {
      'Berkeley Speech Group (BAIR)': 'organization-bsg',
      'Redwood Center for Theoretical Neuroscience (BAIR)': 'organization-redwood',
      'COMPSCI 170 - Algorithms': 'organization-berkeley',
      'COMPSCI 198 - Esolangs': 'organization-berkeley',
      'COMPSCI 70 - Discrete Math & Probability': 'organization-berkeley'
    };
    return organizationMap[organization] || '';
  };

  const getTypeClass = (type) => {
    const typeMap = {
      'Research': 'type-research',
      'Course Staff / Development': 'type-course-staff'
    };
    return typeMap[type] || '';
  };

  return (
    <section className="academics-section">
      <h2 className="section-title">Academia</h2>
      <div className="experience-list">
        {academicExperiences.map((exp, index) => (
          <div key={index} className="experience-item">
            <div className="experience-header">
              <img src={exp.logo} alt={exp.organization} className="company-logo" />
              <div className="experience-info">
                <h3 className="job-title">{exp.title}</h3>
                <h4 className={`organization-name ${getOrganizationClass(exp.organization)}`}>{exp.organization}</h4>
                <p className="duration">{exp.duration}</p>
              </div>
            </div>
            {exp.description.includes('•') ? (
              <div className="description">
                <ul>
                  {exp.description.split('<br>').map((item, index) => (
                    <li key={index} dangerouslySetInnerHTML={{__html: item.replace('• ', '')}}></li>
                  ))}
                </ul>
              </div>
            ) : (
              <p className="description">{exp.description}</p>
            )}
            <div className="technologies">
              {exp.technologies.map((tech, techIndex) => (
                <span key={techIndex} className="tech-tag">{tech}</span>
              ))}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default AcademicsSection;