import React, { useState, useEffect } from 'react';
import './App.css'; // Main styling for the app
import ThreeDExperience from './ThreeDExperience';
import MinimalPortfolio from './components/MinimalPortfolio';



const App = () => {
  const [is3D, setIs3D] = useState(false); // Track whether to show 3D experience

  // Function to handle switching to 3D experience
  const launch3D = () => {
    setIs3D(true); // Switch to the 3D experience view
  };

  // Function to handle going back to 2D portfolio
  const goBack = () => {
    setIs3D(false); // Switch back to the 2D portfolio
  };

  return (
    <div className="root">
      {is3D ? (
        <ThreeDExperience />
      ) : (
        <MinimalPortfolio launch3D={launch3D} />
      )}
    </div>
  );
};

export default App;
